// Задание 9: Датчик температуры LM55
const int lm55Pin = A4;
const int relayPin = 13;
const int thresholdTemp = 80;

void setup() {
  Serial.begin(9600);
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW);
}

void loop() {
  int sensorValue = analogRead(lm55Pin);

  // LM55, как и LM35, имеет чувствительность 10 мВ/°C
  // Но может иметь другой диапазон, здесь предполагаем стандартную формулу
  float voltage = sensorValue * (5.0 / 1024.0);
  float temperature = voltage * 100.0;

  Serial.print("Температура LM55: ");
  Serial.print(temperature);
  Serial.println(" °C");

  if (temperature >= thresholdTemp) {
    digitalWrite(relayPin, HIGH);
    Serial.println("Превышение 80 °C! Реле ВКЛ.");
  } else {
    digitalWrite(relayPin, LOW);
  }
  delay(1000);
}
